56	  public TsFileGenerator(final File tsFile) throws IOException {
57	    this.tsFile = tsFile;
58	    this.writer = new TsFileWriter(tsFile);
59	    this.device2TimeSet = new HashMap<>();
60	    this.device2MeasurementSchema = new HashMap<>();
61	    this.random = new Random();
